import{_ as i,C as c,o as l,c as n,aj as a,E as o,j as e,a as r}from"./chunks/framework.DkvuVDKz.js";const x=JSON.parse('{"title":"InfiniteScroll 无限滚动","description":"","frontmatter":{},"headers":[],"relativePath":"components/infinite-scroll.md","filePath":"components/infinite-scroll.md","lastUpdated":1789272501000}'),h={name:"components/infinite-scroll.md"};function s(b,t,u,g,f,p){const d=c("XhDemo");return l(),n("div",null,[t[0]||(t[0]=a('<h1 id="infinitescroll-无限滚动" tabindex="-1">InfiniteScroll 无限滚动 <a class="header-anchor" href="#infinitescroll-无限滚动" aria-label="Permalink to &quot;InfiniteScroll 无限滚动&quot;">​</a></h1><p>取下一页的通用触发器，滚动只是默认的触发方式。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/infinite-scroll" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/infinite-scroll.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/infinite-scroll" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/infinite-scroll" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/infinite-scroll.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>哨兵滚进可视区就派 load，取完把 loading 写回 false</p>',5)),o(d,{src:"infinite-scroll/01-basic"}),t[1]||(t[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;infinite-scroll&quot;</code>：<strong><code>root</code></strong> · <strong><code>sentinel</code></strong> · <code>load-more-trigger</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="提前量" tabindex="-1">提前量 <a class="header-anchor" href="#提前量" aria-label="Permalink to &quot;提前量&quot;">​</a></h3><p>distance 把可视区沿块轴向外扩，哨兵还没露头就先取下一页</p>',6)),o(d,{src:"infinite-scroll/02-distance"}),t[2]||(t[2]=e("h3",{id:"取到没有了",tabindex:"-1"},[r("取到没有了 "),e("a",{class:"header-anchor",href:"#取到没有了","aria-label":'Permalink to "取到没有了"'},"​")],-1)),t[3]||(t[3]=e("p",null,"最后一页取完把 disabled 打开，哨兵不再被观察，load 也不再派",-1)),o(d,{src:"infinite-scroll/03-disabled"}),t[4]||(t[4]=e("h3",{id:"状态透出",tabindex:"-1"},[r("状态透出 "),e("a",{class:"header-anchor",href:"#状态透出","aria-label":'Permalink to "状态透出"'},"​")],-1)),t[5]||(t[5]=e("p",null,"phase / loading / disabled 由组件交给宿主，加载提示与结束语都由宿主自己摆",-1)),o(d,{src:"infinite-scroll/04-slot-state"}),t[6]||(t[6]=e("h3",{id:"取下一页的按钮",tabindex:"-1"},[r("取下一页的按钮 "),e("a",{class:"header-anchor",href:"#取下一页的按钮","aria-label":'Permalink to "取下一页的按钮"'},"​")],-1)),t[7]||(t[7]=e("p",null,"与哨兵同一条通路：读屏在虚拟光标模式下不产生滚动事件，这颗按钮是它的键盘等价入口",-1)),o(d,{src:"infinite-scroll/05-load-more"}),t[8]||(t[8]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>时间流、消息列表这类用户只关心&quot;再来一些&quot;的内容。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>用户需要跳到确定位置或分享某一页：用<a href="./pagination">分页</a>。</li><li>页面有页脚需要够得着：无限滚动会让页脚永远追不上。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>distance</code> 是提前量：距底部还有这么远就触发，用户感觉不到等待。</li><li><code>loading</code> 与 <code>disabled</code> 由组件交给宿主，加载提示与结束语都由宿主自己摆。</li><li>取完之后关掉即可，不会再触发。</li><li><code>load-more-trigger</code> 是同一条通路的另一个入口：一颗真按钮，取数中与关掉两段自动停用。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与<a href="./list">列表</a>、<a href="./skeleton">骨架屏</a>配合。</li><li>与<a href="./virtualizer">虚拟滚动</a>合成一条边滚边取的长列表：<code>target</code> 指向虚拟滚动的视口，哨兵摆在内容层之后；示例在虚拟滚动那一页。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>明确的结束提示：&quot;没有更多了&quot;比无声停止好。</li><li>加载失败要能重试，别静默停在那里。</li><li>摆一颗 <code>load-more-trigger</code>：读屏在虚拟光标模式下不产生滚动事件，只靠哨兵那条路取不到第二页。</li><li>按钮的文案写在按钮里，组件不代填名字——读屏念的与眼睛看的才是同一句。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>页面底部有重要内容（页脚、版权、联系方式）却用无限滚动。</li><li>不给结束提示，用户一直往下滚。</li><li>与<a href="./virtualizer">虚拟滚动</a>合用时把哨兵摆进条目之间：窗口外的条目不渲染，哨兵也就永远进不了可视区。</li><li>与<a href="./virtualizer">虚拟滚动</a>合用时不给 <code>target</code>：提前量按整页可视区算，而真正在滚的是虚拟滚动的视口那一层。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-infinite-scroll&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhInfiniteScrollLoadMoreTrigger</code> <code>XhInfiniteScrollRoot</code> <code>XhInfiniteScrollSentinel</code></td></tr><tr><td>组合式函数</td><td><code>useInfiniteScroll</code></td></tr><tr><td>状态机</td><td><code>infiniteScrollMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/infinite-scroll.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>distance</code></td><td><code>number</code></td><td></td><td>提前量（px）：哨兵离可视区还有这么远就算进入，默认 0（真正露头才算）。扩的是 getTargetEl 给出的那块可视区。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>关掉：不再观察，也不再触发。列表已经没有下一页时用它。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>正在取数：其间不观察、不重复触发。取完由宿主写回 false。</td></tr><tr><td><code>onLoad</code></td><td><code>() =&gt; void</code></td><td></td><td>该取下一页了。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>load</code></td><td>``</td><td>该取下一页了</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhInfiniteScrollRoot</code></td><td><code>default</code></td><td><code>InfiniteScrollRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>loading</code> · <code>paused</code></p><p><strong>事件</strong>：<code>SENTINEL.ENTER</code> · <code>LOAD</code> · <code>MODE.SYNC</code></p><p><strong>判据</strong>：<code>isPaused</code> · <code>isLoading</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>InfiniteScrollPhase</code></td><td></td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td>正在取数。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td>已关掉，不再观察。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSentinelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLoadMoreTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td>取下一页的按钮。文案由作者写在按钮里，组件不代填。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>sentinel</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/infinite-scroll.css</code> 使用 <code>[data-scope=&quot;infinite-scroll&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>load-more-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>load-more-trigger</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-infinite-scroll-load-more-bg</code></td><td><code>load-more-trigger</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-canvas</code></td><td>infinite-scroll 的 load-more-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-bg-active</code></td><td><code>load-more-trigger</code></td><td><code>background</code></td><td><code>active</code></td><td><code>--xh-bg-subtle-active</code></td><td>infinite-scroll 的 load-more-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-bg-hover</code></td><td><code>load-more-trigger</code></td><td><code>background</code></td><td><code>hover</code></td><td><code>--xh-bg-subtle-hover</code></td><td>infinite-scroll 的 load-more-trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-border</code></td><td><code>load-more-trigger</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-control</code></td><td>infinite-scroll 的 load-more-trigger 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-border-hover</code></td><td><code>load-more-trigger</code></td><td><code>border-color</code></td><td><code>hover</code></td><td><code>--xh-border-control-hover</code></td><td>infinite-scroll 的 load-more-trigger 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-fg</code></td><td><code>load-more-trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>infinite-scroll 的 load-more-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-font-size</code></td><td><code>load-more-trigger</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-body-size</code></td><td>infinite-scroll 的 load-more-trigger 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-gap</code></td><td><code>load-more-trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-control-gap-md</code></td><td>infinite-scroll 的 load-more-trigger 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-h</code></td><td><code>load-more-trigger</code></td><td><code>min-block-size</code></td><td><code>default</code></td><td><code>--xh-control-h-md</code></td><td>infinite-scroll 的 load-more-trigger 部件 min-block-size 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-px</code></td><td><code>load-more-trigger</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-control-px-md</code></td><td>infinite-scroll 的 load-more-trigger 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-load-more-radius</code></td><td><code>load-more-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>infinite-scroll 的 load-more-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-infinite-scroll-sentinel-size</code></td><td><code>sentinel</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-stroke-thin</code></td><td>infinite-scroll 的 sentinel 部件 block-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>border-color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',53))])}const q=i(h,[["render",s]]);export{x as __pageData,q as default};
